"""The operator's chart-review sheet for a model's trades (D-148).

    python scripts/review_sheet.py fv1 NQ

FV1: the configuration selected on 2009-2011, at ACTUAL prices, on the 2014-2019 run (R047/R048), so the times can be
read straight off a one-minute chart. FV1's signals do not depend on the price scale (displacement is a ratio, a break
compares two prices, the side of fair value is a comparison), so the actual-scale trades are the trades a chart shows.
FV1's kits (made before D-148) export no prices: the sheet asks for the judgement a chart gives without them.

Writes docs/reviews/FV1_<market>_review.md and results/review_fv1_<market>.csv (the same rows, for filling in).
"""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
sys.dont_write_bytecode = True

import yaml  # noqa: E402

from propedge.data.qc_algorithms import FV_EXT_RUNS  # noqa: E402
from propedge.reporting.results import read_result, write_result  # noqa: E402
from propedge.research import fv_score as fs  # noqa: E402
from propedge.research.trade_audit import review_sample  # noqa: E402

SEED = 20261106
N, EXTREMES = 20, 3
FV1_QUESTIONS = (
    "Fair value is the 09:30 ET open (08:30 CT; 14:00 ET / 13:00 CT in the afternoon). Continuation (first 15 minutes): "
    "price already on the trade's side of fair value. Reversion: price on the far side, trading back toward it.",
    "The signal bar (it closes at the time given) is a displacement candle: closes in the trade's direction with a small "
    "counter-wick (under 20 % of its open-to-extreme range).",
    "Its close breaks the recent leg's high (long) or low (short): would you call it a BOS or an MSB? FV1 uses the most "
    "recent two-bar swing point; if the swing you would have used is a different, larger one, say so.",
    "The entry is the next bar's open; the stop one tick beyond the opposite swing, or the minimum distance "
    "({floor} ticks, {floor_pts:g} points) when the swing is closer; the target 1.5 times the stop. A stop at exactly "
    "the minimum means the swing FV1 used was closer than that.",
)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("model", choices=["fv1"])
    ap.add_argument("market", choices=sorted(FV_EXT_RUNS))
    a = ap.parse_args(argv)
    cfg = yaml.safe_load((ROOT / "config" / "model_fv.yaml").read_text(encoding="utf-8"))
    sel = read_result(ROOT / "results" / f"fv1_{a.market}.csv")
    sel = sel[(sel["section"] == "selection") & (sel["statistic"] == "selected")].iloc[0]
    run = FV_EXT_RUNS[a.market]
    days, trades = fs.split(read_result(ROOT / "results" / f"manual_{run.replace('-', '_')}.csv"))
    block = days[fs.eligible(days)]["n"].tolist()
    tr = fs.configuration(trades, sel["family"], sel["window"], "actual")
    log = fs.trade_log(tr[tr["n"].isin(block)], tick_value=float(cfg["markets"][a.market]["tick_value"]), risk=500.0,
                       cap_micros=37)
    keep = ["date", "session", "setup", "side", "signal_bar_close_ct", "entry_ct", "exit_bar_ct", "exit",
            "stop_ticks", "r_net"]
    s = review_sample(log[keep], n=N, seed=SEED, extremes=EXTREMES)
    name = f"review_fv1_{a.market}"
    write_result(s, name, script="scripts/review_sheet.py", seed=SEED,
                 parameters={"model": "FV1", "market": a.market, "run": run, "configuration":
                             f"{sel['family']}/{sel['window']}", "scale": "actual", "random": N, "extremes": EXTREMES},
                 notes={"decision": "D-148", "for": "the operator's chart review"},
                 description=f"FV1 {a.market}: the seeded chart-review sample (actual prices, 2014-2019).")
    lines = [f"# FV1 on {a.market}: chart review", "",
             f"Generated by `scripts/review_sheet.py` from `results/{name}.csv` (seed {SEED}); fill in the CSV or "
             "answer here. For each trade, open a one-minute chart of the front contract "
             f"({'NQ1!' if a.market == 'NQ' else 'ES1!'} on TradingView) at the date and time given (ET beside CT).",
             "", f"Configuration: {sel['family']} stops, window {sel['window']}, actual prices, 2014-2019 ({run}).",
             "", "## What to check on each trade", ""]
    mk = cfg["markets"][a.market]
    fill = {"floor": int(mk["floor_ticks"]), "floor_pts": int(mk["floor_ticks"]) * float(mk["tick"])}
    lines += [f"{i}. {q.format(**fill)}" for i, q in enumerate(FV1_QUESTIONS, 1)]
    lines += ["", "Then: setup valid (y/n); entry, stop and target where the rules put them (y/n); exit where and when "
              "the chart says (y/n); a note for anything that looks wrong.", "", "## The trades", "",
              "| # | why | date | session | setup | side | signal bar closes (ET) | entry (ET) | exit bar (ET) | exit | "
              "stop (ticks) | R |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for i, r in s.iterrows():
        lines.append(f"| {i + 1} | {r['why']} | {r['date']} | {r['session']} | {r['setup']} | {r['side']} | "
                     f"{r['signal_bar_close_et']} | {r['entry_et']} | {r['exit_bar_et']} | {r['exit']} | "
                     f"{r['stop_ticks']} | {r['r_net']:+.2f} |")
    out = ROOT / "docs" / "reviews" / f"FV1_{a.market}_review.md"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
    print(f"wrote {out.relative_to(ROOT)} ({len(s)} trades)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
